// LoadAlertRule loads the alertState's AlertRule into the .R struct
func (o *AlertState) LoadAlertRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AlertRule = nil
	o.R.Loaded.AlertRule = false

	related, err := o.AlertRule(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AlertStates = AlertStateSlice{o}

	o.R.AlertRule = related
	o.R.Loaded.AlertRule = true
	return nil
}

// LoadAlertRule loads the alertState's AlertRule into the .R struct
func (os AlertStateSlice) LoadAlertRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	alertRules, err := os.AlertRule(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AlertRule = nil
		o.R.Loaded.AlertRule = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	alertStateByKey := make(map[string][]*AlertState, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		alertStateByKey[o.AlertRuleID] = append(alertStateByKey[o.AlertRuleID], o)
	}

	for _, rel := range alertRules {

		owners, ok := alertStateByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.AlertRule != nil {
				continue
			}

			rel.R.AlertStates = append(rel.R.AlertStates, o)

			o.R.AlertRule = rel

		}
	}

	return nil
}

type alertStateJoins[Q dialect.Joinable] struct {
	typ       string
	AlertRule modAs[Q, alertRuleColumns]
}

func (j alertStateJoins[Q]) aliasedAs(alias string) alertStateJoins[Q] {
	return buildAlertStateJoins[Q](buildAlertStateColumns(alias), j.typ)
}

func buildAlertStateJoins[Q dialect.Joinable](cols alertStateColumns, typ string) alertStateJoins[Q] {
	return alertStateJoins[Q]{
		typ: typ,
		AlertRule: modAs[Q, alertRuleColumns]{
			c: AlertRules.Columns,
			f: func(to alertRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertRules.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.AlertRuleID),
					))
				}

				return mods
			},
		},
	}
}
